<?php use App\Helpers\UI; ?>
<div class="page-header"><div><h1 class="page-title"><?= e($title) ?></h1><p class="text-muted">ข้อมูลตามสิทธิ์และโรงแรมที่เลือก</p></div><div class="d-flex gap-2 flex-wrap"><?php foreach ($links as $path => $caption): ?><a class="btn btn-outline-primary" href="<?= e(url($path)) ?>"><?= e($caption) ?></a><?php endforeach ?></div></div>
<?php if ($notice): ?><div class="alert alert-info"><?= e($notice) ?></div><?php endif ?>
<?php if(!empty($searchable)): ?><form method="get" class="mb-3 d-flex gap-2 flex-wrap align-items-end"><label class="flex-grow-1">ค้นหา<input name="q" value="<?= e($search ?? '') ?>" class="form-control" placeholder="ค้นหา"></label>
<?php if(!empty($dateFilters)): ?><?php [$filterFrom,$filterTo]=\App\Services\KPIService::range($query['from']??null,$query['to']??null); ?><label>ตั้งแต่<input name="from" type="date" class="form-control" value="<?= e($filterFrom) ?>"></label><label>ถึง<input name="to" type="date" class="form-control" value="<?= e($filterTo) ?>"></label><?php endif ?>
<?php if(isset($query['year'])): ?><label>ปี ค.ศ.<input name="year" type="number" class="form-control" min="2000" max="2200" value="<?= e($query['year']) ?>"></label><?php endif ?>
<?php if(isset($query['status'])): ?><input type="hidden" name="status" value="<?= e($query['status']) ?>"><?php endif ?><button class="btn btn-light">ค้นหา / กรอง</button></form><?php endif ?>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><?php foreach ($columns as $caption): ?><th scope="col"><?= e($caption) ?></th><?php endforeach ?><?php if ($actions): ?><th scope="col">ดำเนินการ</th><?php endif ?></tr></thead><tbody>
<?php foreach ($rows as $row): ?><tr><?php foreach ($columns as $key => $caption):
    $value=$row[$key]??'—';
    if(in_array($key,['hotel_id','from_hotel_id','to_hotel_id'])&&$value!=='—'){$value=\App\Core\HotelContext::hotel((int)$value)['code']??$value;}
?><td><?php if($key==='status'&&isset(\App\Models\TicketStatus::LABELS[$value])): ?><?= UI::status($value) ?><?php elseif($key==='status'): ?><?= UI::soft(\App\Services\AssetService::STATUSES[$value]??['PENDING'=>'รออนุมัติ','APPROVED'=>'อนุมัติแล้ว','REJECTED'=>'ไม่อนุมัติ','VOID'=>'ยกเลิกต้นทุน','REQUESTED'=>'ขอโอน','IN_TRANSIT'=>'ระหว่างขนส่ง','RECEIVED'=>'รับเข้าแล้ว','SUBMITTED'=>'รอพิจารณา','DISCOVERED'=>'ค้นพบกลุ่ม','BOUND'=>'ผูกกลุ่มแล้ว','DISABLED'=>'ปิดใช้','LEFT'=>'ออกจากกลุ่ม','SENT'=>'ประมวลผลแล้ว','FAILED'=>'ล้มเหลว รอลองใหม่','DEAD'=>'หยุดลองใหม่','SKIPPED'=>'ข้ามรายการ','PROCESSING'=>'กำลังส่ง'][$value]??(string)$value) ?><?php else: ?><?= e($value) ?><?php endif ?></td><?php endforeach ?><?php if ($actions): ?><td><?= $actions($row) ?></td><?php endif ?></tr><?php endforeach ?>
</tbody></table></div><?php if (!$rows): ?><?= UI::empty('ยังไม่มีรายการ', 'เพิ่มข้อมูลหรือเปลี่ยนโรงแรมและเงื่อนไขค้นหา') ?><?php endif ?></div>
<?php foreach ($forms as $f): ?><div class="mt-4"><?= $this->partial('shared/form', ['title' => $f['title'], 'action' => $f['action'], 'fields' => $f['fields'], 'values' => $f['values'] ?? [], 'notice' => $f['notice'] ?? '']) ?></div><?php endforeach ?>
